Dataspatium.assets.register("presets/ids/SE-Dataspatium_Grund.ids","text","<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!-- SPDX-License-Identifier: LicenseRef-PolyForm-Strict-1.0.0 -->\n<!-- Dataspatium's own requirements, written from open rules (buildingSMART's IFC documentation and the bSI rules OJT001 and\n     IFC102, and the naming rules of the guidance Praxi in the app's own words); no text, list or template of Praxi is copied.\n     The pattern in the PredefinedType specifications takes every value except an empty one and the words NOTDEFINED and\n     USERDEFINED themselves, so that a standard value passes and so does USERDEFINED with an ObjectType, which IDS reads as the\n     ObjectType; USERDEFINED without one fails. IDS names a class without its subtypes, so the IFC4 classes ...StandardCase and\n     IfcSlabElementedCase have specifications of their own. -->\n<ids xmlns=\"http://standards.buildingsmart.org/IDS\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://standards.buildingsmart.org/IDS http://standards.buildingsmart.org/IDS/1.0/ids.xsd\">\n  <info>\n    <title>SE-Dataspatium_Grund</title>\n    <copyright>Dataspatium</copyright>\n    <version>1.0</version>\n    <description>Grundkrav på en byggnadsmodell: namn på plats, byggnad, våningar och rum, inga proxyelement, och en PredefinedType på bjälklag, tak, dörrar, fönster och beklädnader.</description>\n    <date>2026-11-12</date>\n    <purpose>Grunduppgifter för varje syfte</purpose>\n  </info>\n  <specifications>\n    <specification name=\"Platsen har ett namn\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G01\" description=\"IfcSite.Name är satt, till exempel fastighetsbeteckningen.\" instructions=\"Ge platsen ett namn.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSITE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <attribute cardinality=\"required\"><name><simpleValue>Name</simpleValue></name></attribute>\n      </requirements>\n    </specification>\n    <specification name=\"Byggnaden har ett namn\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G02\" description=\"IfcBuilding.Name är satt, till exempel byggnadens nummer.\" instructions=\"Ge byggnaden ett namn eller nummer.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCBUILDING</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <attribute cardinality=\"required\"><name><simpleValue>Name</simpleValue></name></attribute>\n      </requirements>\n    </specification>\n    <specification name=\"Våningen har ett namn\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G03\" description=\"IfcBuildingStorey.Name är satt.\" instructions=\"Ge varje våning ett namn.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCBUILDINGSTOREY</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <attribute cardinality=\"required\"><name><simpleValue>Name</simpleValue></name></attribute>\n      </requirements>\n    </specification>\n    <specification name=\"Rummet har ett nummer\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G04\" description=\"IfcSpace.Name är satt: rummets nummer; namnet står i LongName.\" instructions=\"Ge varje rum ett nummer i Name.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSPACE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <attribute cardinality=\"required\"><name><simpleValue>Name</simpleValue></name></attribute>\n      </requirements>\n    </specification>\n    <specification name=\"Inga proxyelement\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G05\" description=\"Ingen byggdel är IfcBuildingElementProxy; varje byggdel har den klass som säger vad den är.\" instructions=\"Byt proxyelementen mot den klass som passar.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"0\">\n        <entity><name><simpleValue>IFCBUILDINGELEMENTPROXY</simpleValue></name></entity>\n      </applicability>\n    </specification>\n    <specification name=\"Bjälklaget har en PredefinedType\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G06\" description=\"IfcSlab har en PredefinedType, på elementet eller dess typ, och inte NOTDEFINED: FLOOR, ROOF, BASESLAB och så vidare.\" instructions=\"Ange bjälklagets PredefinedType, helst på typen.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSLAB</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCSLAB</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Taket har en form\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"G07\" description=\"IfcRoof har en PredefinedType, till exempel GABLE_ROOF eller FLAT_ROOF, och inte NOTDEFINED.\" instructions=\"Ange takets form som PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCROOF</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCROOF</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Dörren har en PredefinedType\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"G08\" description=\"IfcDoor har en PredefinedType, till exempel DOOR eller GATE, och inte NOTDEFINED.\" instructions=\"Ange dörrens PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCDOOR</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCDOOR</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Fönstret har en PredefinedType\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"G09\" description=\"IfcWindow har en PredefinedType, till exempel WINDOW eller SKYLIGHT, och inte NOTDEFINED.\" instructions=\"Ange fönstrets PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWINDOW</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCWINDOW</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Beklädnaden har en PredefinedType\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"G10\" description=\"IfcCovering har en PredefinedType, till exempel FLOORING, CEILING eller CLADDING, och inte NOTDEFINED.\" instructions=\"Ange beklädnadens PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCCOVERING</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCCOVERING</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Bjälklaget (IfcSlabStandardCase) har en PredefinedType\" ifcVersion=\"IFC4\" identifier=\"G11\" description=\"IfcSlabStandardCase (IFC4) har en PredefinedType, på elementet eller dess typ, och inte NOTDEFINED.\" instructions=\"Ange bjälklagets PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSLABSTANDARDCASE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCSLABSTANDARDCASE</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Bjälklaget (IfcSlabElementedCase) har en PredefinedType\" ifcVersion=\"IFC4\" identifier=\"G12\" description=\"IfcSlabElementedCase (IFC4) har en PredefinedType, på elementet eller dess typ, och inte NOTDEFINED.\" instructions=\"Ange bjälklagets PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSLABELEMENTEDCASE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCSLABELEMENTEDCASE</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Dörren (IfcDoorStandardCase) har en PredefinedType\" ifcVersion=\"IFC4\" identifier=\"G13\" description=\"IfcDoorStandardCase (IFC4) har en PredefinedType, på elementet eller dess typ, och inte NOTDEFINED.\" instructions=\"Ange dörrens PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCDOORSTANDARDCASE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCDOORSTANDARDCASE</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n    <specification name=\"Fönstret (IfcWindowStandardCase) har en PredefinedType\" ifcVersion=\"IFC4\" identifier=\"G14\" description=\"IfcWindowStandardCase (IFC4) har en PredefinedType, på elementet eller dess typ, och inte NOTDEFINED.\" instructions=\"Ange fönstrets PredefinedType.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWINDOWSTANDARDCASE</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <entity>\n          <name><simpleValue>IFCWINDOWSTANDARDCASE</simpleValue></name>\n          <predefinedType><xs:restriction base=\"xs:string\"><xs:pattern value=\"[^NU].*|N([^O].*)?|NO([^T].*)?|NOT([^D].*)?|NOTD([^E].*)?|NOTDE([^F].*)?|NOTDEF([^I].*)?|NOTDEFI([^N].*)?|NOTDEFIN([^E].*)?|NOTDEFINE([^D].*)?|NOTDEFINED.+|U([^S].*)?|US([^E].*)?|USE([^R].*)?|USER([^D].*)?|USERD([^E].*)?|USERDE([^F].*)?|USERDEF([^I].*)?|USERDEFI([^N].*)?|USERDEFIN([^E].*)?|USERDEFINE([^D].*)?|USERDEFINED.+\"/></xs:restriction></predefinedType>\n        </entity>\n      </requirements>\n    </specification>\n  </specifications>\n</ids>\n");
